{{- if .Values.web.enabled -}}
apiVersion: apps/v1
kind: Deployment
metadata:
  namespace: {{ include "temporal.kubernetesNamespace" $ }}
  name: {{ include "temporal.componentname" (list $ "web") }}
  annotations:
    {{- include "temporal.resourceAnnotations" (list $ "web" "deployment") | nindent 4 }}
  labels:
    {{- include "temporal.resourceLabels" (list $ "web" "deployment") | nindent 4 }}
spec:
  {{- with .Values.web.replicaCount }}
  replicas: {{ . }}
  {{- end }}
  {{- with .Values.web.deploymentStrategy }}
  strategy:
  {{- toYaml . | nindent 4 }}
  {{- end }}
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ include "temporal.name" $ }}
      app.kubernetes.io/instance: {{ .Release.Name }}
      app.kubernetes.io/component: web
  {{- with .Values.web.minReadySeconds }}
  minReadySeconds: {{ . }}
  {{- end }}
  template:
    metadata:
      annotations:
        {{- include "temporal.resourceAnnotations" (list $ "web" "pod") | nindent 8 }}
      labels:
        {{- include "temporal.resourceLabels" (list $ "web" "pod") | nindent 8 }}
    spec:
      {{- with .Values.web.additionalInitContainers }}
      initContainers:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{ include "temporal.componentServiceAccount" (list $ "web") }}
      {{- if or .Values.web.additionalVolumes .Values.web.tls.enabled }}
      volumes:
      {{- if .Values.web.additionalVolumes }}
      {{- toYaml .Values.web.additionalVolumes | nindent 8 }}
      {{- end }}
      {{- if .Values.web.tls.enabled }}
      {{- include "temporal.web.tls.volumes" $ | nindent 8 }}
      {{- end }}
      {{- end }}
      containers:
        - name: {{ .Chart.Name }}-web
          image: "{{ .Values.web.image.repository }}:{{ .Values.web.image.tag }}"
          imagePullPolicy: {{ .Values.web.image.pullPolicy }}
          env:
            - name: TEMPORAL_ADDRESS
              {{- if .Values.web.temporalAddress }}
              value: {{ .Values.web.temporalAddress }}
              {{- else }}
              value: {{ include "temporal.frontendAddress" $ }}
              {{- end }}
          {{- if .Values.web.tls.enabled }}
          {{- include "temporal.web.tls.env" $ | nindent 12 }}
          {{- end }}
          {{- if .Values.web.additionalEnv }}
          {{- toYaml .Values.web.additionalEnv | nindent 12 }}
          {{- end }}
          {{- if or .Values.web.additionalEnvSecretName .Values.web.additionalEnvConfigMapName }}
          envFrom:
          {{- if .Values.web.additionalEnvSecretName }}
            - secretRef:
                name: {{ .Values.web.additionalEnvSecretName }}
          {{- end }}
          {{- if .Values.web.additionalEnvConfigMapName }}
            - configMapRef:
                name: {{ .Values.web.additionalEnvConfigMapName }}
          {{- end }}
          {{- end }}
          livenessProbe:
            initialDelaySeconds: 10
            tcpSocket:
              port: http
          {{- with .Values.web.readinessProbe }}
          readinessProbe:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          ports:
            - name: http
              containerPort: 8080
              protocol: TCP
          resources:
            {{- toYaml .Values.web.resources | nindent 12 }}
          {{- with .Values.web.containerSecurityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- if or .Values.web.additionalVolumeMounts .Values.web.tls.enabled }}
          volumeMounts:
          {{- if .Values.web.additionalVolumeMounts }}
            {{- toYaml .Values.web.additionalVolumeMounts | nindent 12 }}
          {{- end }}
          {{- if .Values.web.tls.enabled }}
          {{- include "temporal.web.tls.volumeMounts" $ | nindent 12 }}
          {{- end }}
          {{- end }}
      {{- with .Values.web.securityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with $.Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.web.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    {{- with .Values.web.affinity }}
      affinity:
      {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.web.tolerations }}
      tolerations:
      {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.web.topologySpreadConstraints }}
      topologySpreadConstraints:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.web.schedulerName }}
      schedulerName: {{ . }}
    {{- end }}
    {{- with .Values.web.runtimeClassName }}
      runtimeClassName: {{ . }}
    {{- end }}
    {{- with .Values.web.priorityClassName }}
      priorityClassName: {{ . }}
    {{- end }}
  {{- end }}

{{- $rendered := include "temporal-proxy.rendered" . | fromYaml }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "temporal-proxy.fullname" . }}
  namespace: {{ include "temporal-proxy.namespace" . }}
  labels:
    {{- include "temporal-proxy.labels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  {{- with .Values.strategy }}
  strategy:
    {{- toYaml . | nindent 4 }}
  {{- end }}
  {{- with .Values.minReadySeconds }}
  minReadySeconds: {{ . }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "temporal-proxy.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "temporal-proxy.labels" . | nindent 8 }}
        {{- with .Values.podLabels }}
          {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "temporal-proxy.serviceAccountName" . }}
      {{- with .Values.terminationGracePeriodSeconds }}
      terminationGracePeriodSeconds: {{ . }}
      {{- end }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: {{ .Chart.Name }}
          {{- with .Values.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          args:
            - serve
          env:
            - name: PROXY_CONFIG
              value: /etc/temporal-proxy/config.yaml
            {{- with $rendered.env }}
              {{- toYaml . | nindent 12 }}
            {{- end }}
            {{- with .Values.env }}
              {{- toYaml . | nindent 12 }}
            {{- end }}
          {{- with .Values.envFrom }}
          envFrom:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          ports:
            - name: http
              containerPort: {{ .Values.service.port }}
              protocol: TCP
          {{- with .Values.livenessProbe }}
          livenessProbe:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.readinessProbe }}
          readinessProbe:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.lifecycle }}
          lifecycle:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          volumeMounts:
            - name: config
              mountPath: /etc/temporal-proxy
          {{- with $rendered.volumeMounts }}
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.volumeMounts }}
            {{- toYaml . | nindent 12 }}
          {{- end }}
      volumes:
        - name: config
          configMap:
            name: {{ include "temporal-proxy.fullname" . }}
      {{- with $rendered.volumes }}
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.volumes }}
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

{{- if $.Values.admintools.enabled }}
{{- /* By default the admin tools target the internal-frontend when it is enabled
(which grants admin without an external Authorizer); set
admintools.useExternalFrontend to true to route through the external frontend
instead. The two paths terminate TLS with different certificates, so resolve the
section accordingly. A custom admintools.temporalAddress points somewhere the
chart cannot reason about, so skip chart-managed TLS then and let the user wire
it via admintools.additionalEnv/additionalVolumes. */}}
{{- $useInternalFrontend := and (index $.Values.server "internal-frontend").enabled (not $.Values.admintools.useExternalFrontend) }}
{{- $tlsSection := "" }}
{{- if not $.Values.admintools.temporalAddress }}
{{- $tlsSection = include "temporal.adminClient.tls.section" (list $ $useInternalFrontend) }}
{{- end }}
apiVersion: apps/v1
kind: Deployment
metadata:
  namespace: {{ include "temporal.kubernetesNamespace" $ }}
  name: {{ include "temporal.componentname" (list $ "admintools") }}
  annotations:
    {{- include "temporal.resourceAnnotations" (list $ "admintools" "deployment") | nindent 4 }}
  labels:
    {{- include "temporal.resourceLabels" (list $ "admintools" "deployment") | nindent 4 }}
spec:
  replicas: 1
  {{- with .Values.admintools.deploymentStrategy }}
  strategy:
  {{- toYaml . | nindent 4 }}
  {{- end }}
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ include "temporal.name" $ }}
      app.kubernetes.io/instance: {{ .Release.Name }}
      app.kubernetes.io/component: admintools
  {{- with .Values.admintools.minReadySeconds }}
  minReadySeconds: {{ . }}
  {{- end }}
  template:
    metadata:
      annotations:
        {{- include "temporal.resourceAnnotations" (list $ "admintools" "pod") | nindent 8 }}
      labels:
        {{- include "temporal.resourceLabels" (list $ "admintools" "pod") | nindent 8 }}
    spec:
      {{ include "temporal.componentServiceAccount" (list $ "admintools") }}
      {{- with $.Values.admintools.additionalInitContainers }}
      initContainers:
        {{- toYaml .| nindent 8 }}
      {{- end }}
      containers:
        - name: admin-tools
          image: "{{ .Values.admintools.image.repository }}:{{ .Values.admintools.image.tag }}"
          imagePullPolicy: {{ .Values.admintools.image.pullPolicy }}
          env:
            # TEMPORAL_CLI_ADDRESS is deprecated, use TEMPORAL_ADDRESS instead
            - name: TEMPORAL_CLI_ADDRESS
              {{- if $useInternalFrontend }}
              value: {{ include "temporal.internalFrontendAddress" $ }}
              {{- else }}
              value: {{ include "temporal.frontendAddress" $ }}
              {{- end }}
            - name: TEMPORAL_ADDRESS
              {{- if .Values.admintools.temporalAddress }}
              value: {{ .Values.admintools.temporalAddress }}
              {{- else if $useInternalFrontend }}
              value: {{ include "temporal.internalFrontendAddress" $ }}
              {{- else }}
              value: {{ include "temporal.frontendAddress" $ }}
              {{- end }}
          {{- if $tlsSection }}
          {{- include "temporal.adminClient.tls.env" (list $ $tlsSection) | nindent 12 }}
          {{- end }}
          {{- with .Values.admintools.additionalEnv }}
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- if or .Values.admintools.additionalEnvSecretName .Values.admintools.additionalEnvConfigMapName }}
          envFrom:
          {{- with .Values.admintools.additionalEnvSecretName }}
            - secretRef:
                name: {{ . }}
          {{- end }}
          {{- with .Values.admintools.additionalEnvConfigMapName }}
            - configMapRef:
                name: {{ . }}
          {{- end }}
          {{- end }}
          livenessProbe:
              exec:
                command:
                - ls
                - /
              initialDelaySeconds: 5
              periodSeconds: 5
          {{- if or $.Values.admintools.additionalVolumeMounts $tlsSection }}
          volumeMounts:
          {{- with $.Values.admintools.additionalVolumeMounts }}
            {{- toYaml . | nindent 12}}
          {{- end }}
          {{- if $tlsSection }}
          {{- include "temporal.adminClient.tls.volumeMounts" (list $ $tlsSection) | nindent 12 }}
          {{- end }}
          {{- end }}
          {{- with .Values.admintools.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.admintools.containerSecurityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      {{- with .Values.admintools.securityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with $.Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- if or $.Values.admintools.additionalVolumes $tlsSection }}
      volumes:
      {{- with $.Values.admintools.additionalVolumes }}
        {{- toYaml . | nindent 8}}
      {{- end }}
      {{- if $tlsSection }}
      {{- include "temporal.adminClient.tls.volumes" (list $ $tlsSection) | nindent 8 }}
      {{- end }}
      {{- end }}
      {{- with .Values.admintools.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    {{- with .Values.admintools.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.admintools.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.admintools.schedulerName }}
      schedulerName: {{ . }}
    {{- end }}
    {{- with .Values.admintools.runtimeClassName }}
      runtimeClassName: {{ . }}
    {{- end }}
    {{- with .Values.admintools.priorityClassName }}
      priorityClassName: {{ . }}
    {{- end }}
{{- end }}

{{- if $.Values.server.enabled }}
{{- $defaultStore := include "temporal.persistence.getStoreByType" (list $ "default") | fromYaml -}}
{{- $visibilityStore := include "temporal.persistence.getStoreByType" (list $ "visibility") | fromYaml -}}
{{- $secondaryVisibilityStore := include "temporal.persistence.getStoreByType" (list $ "secondaryVisibility") | fromYaml -}}
{{- range $service := (list "frontend" "internal-frontend" "history" "matching" "worker") }}
{{- $serviceValues := index $.Values.server $service }}
{{- if $serviceValues.enabled }}
{{- $image := merge (deepCopy ($serviceValues.image | default dict)) $.Values.server.image }}
apiVersion: apps/v1
kind: Deployment
metadata:
  namespace: {{ include "temporal.kubernetesNamespace" $ }}
  name: {{ include "temporal.componentname" (list $ $service) }}
  annotations:
    {{- include "temporal.resourceAnnotations" (list $ $service "deployment") | nindent 4 }}
  labels:
    {{- include "temporal.resourceLabels" (list $ $service "deployment") | nindent 4 }}
spec:
  {{- if $serviceValues.replicaCount }}
  replicas: {{ $serviceValues.replicaCount }}
  {{- else if $.Values.server.replicaCount }}
  replicas: {{ $.Values.server.replicaCount }}
  {{- end }}
  {{- with (default $.Values.server.deploymentStrategy $serviceValues.deploymentStrategy) }}
  strategy:
  {{- toYaml . | nindent 4 }}
  {{- end }}
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ include "temporal.name" $ }}
      app.kubernetes.io/instance: {{ $.Release.Name }}
      app.kubernetes.io/component: {{ $service }}
  {{- with (default $.Values.server.minReadySeconds $serviceValues.minReadySeconds) }}
  minReadySeconds: {{ . }}
  {{- end }}
  template:
    metadata:
      annotations:
        checksum/config: {{ include (print $.Template.BasePath "/server-configmap.yaml") $ | sha256sum }}
        {{- if (dig "metrics" "annotations" "enabled" $.Values.server.metrics.annotations.enabled $serviceValues) }}
        prometheus.io/job: {{ $.Chart.Name }}-{{ $service }}
        prometheus.io/scrape: 'true'
        prometheus.io/scheme: http
        prometheus.io/port: '9090'
        {{- end }}
        {{- include "temporal.resourceAnnotations" (list $ $service "pod") | nindent 8 }}
      labels:
        {{- include "temporal.resourceLabels" (list $ $service "pod") | nindent 8 }}
    spec:
      {{ include "temporal.componentServiceAccount" (list $ $service) }}
      {{- with $.Values.server.securityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- if $.Values.server.additionalInitContainers }}
      initContainers:
        {{- toYaml $.Values.server.additionalInitContainers | nindent 8 }}
      {{- end }}
      containers:
        - name: {{ $.Chart.Name }}-{{ $service }}
          image: "{{ $image.repository }}:{{ $image.tag }}"
          imagePullPolicy: {{ $image.pullPolicy }}
          env:
            - name: POD_IP
              valueFrom:
                fieldRef:
                  fieldPath: status.podIP
            - name: SERVICES
              value: {{ $service }}
            - name: TEMPORAL_SERVICES
              value: {{ $service }}
            - name: TEMPORAL_SERVER_CONFIG_FILE_PATH
              value: /etc/temporal/config/config_template.yaml
          {{- if not (and (eq $defaultStore.driver "sql") $defaultStore.config.passwordCommand) }}
            - name: TEMPORAL_DEFAULT_STORE_PASSWORD
              {{- include "temporal.password-env" (list $ $defaultStore) | nindent 14 }}
          {{- end }}
          {{- if not (and (eq $visibilityStore.driver "sql") $visibilityStore.config.passwordCommand) }}
            - name: TEMPORAL_VISIBILITY_STORE_PASSWORD
              {{- include "temporal.password-env" (list $ $visibilityStore) | nindent 14 }}
          {{- end }}
          {{- if and $secondaryVisibilityStore (not (and (eq $secondaryVisibilityStore.driver "sql") $secondaryVisibilityStore.config.passwordCommand)) }}
            - name: TEMPORAL_SECONDARY_VISIBILITY_STORE_PASSWORD
              {{- include "temporal.password-env" (list $ $secondaryVisibilityStore) | nindent 14 }}
          {{- end }}
          {{- if (index $.Values.server "internal-frontend").enabled }}
            - name: USE_INTERNAL_FRONTEND
              value: "1"
          {{- end }}
          {{- if $.Values.server.versionCheckDisabled }}
            - name: TEMPORAL_VERSION_CHECK_DISABLED
              value: "1"
          {{- end }}
          {{- if or $.Values.server.additionalEnv $serviceValues.additionalEnv }}
          {{- toYaml (default $.Values.server.additionalEnv $serviceValues.additionalEnv) | nindent 12 }}
          {{- end }}
          {{- if or $.Values.server.additionalEnvSecretName $.Values.server.additionalEnvConfigMapName }}
          envFrom:
          {{- if $.Values.server.additionalEnvSecretName }}
            - secretRef:
                name: {{ $.Values.server.additionalEnvSecretName }}
          {{- end }}
          {{- if $.Values.server.additionalEnvConfigMapName }}
            - configMapRef:
                name: {{ $.Values.server.additionalEnvConfigMapName }}
          {{- end }}
          {{- end }}
          # For Istio service mesh - make sure ports are defined here and in the headless service, see:
          # https://istio.io/latest/docs/ops/configuration/traffic-management/traffic-routing/#headless-services
          ports:
          {{- if ne $service "worker" }}
            - name: rpc
              containerPort: {{ $serviceValues.service.port }}
              protocol: TCP
          {{- end }}
            - name: membership
              containerPort: {{ $serviceValues.service.membershipPort }}
              protocol: TCP
          {{- if or (eq $service "frontend") (eq $service "internal-frontend") }}
            - name: http
              containerPort: {{ $serviceValues.service.httpPort }}
              protocol: TCP
          {{- end }}
            - name: metrics
              containerPort: 9090
              protocol: TCP
          {{- $resolvedLiveness := default $.Values.server.livenessProbe $serviceValues.livenessProbe }}
          {{- if $resolvedLiveness }}
          livenessProbe:
          {{- toYaml $resolvedLiveness | nindent 12 }}
          {{- else if ne $service "worker" }}
          livenessProbe:
            initialDelaySeconds: 150
            tcpSocket:
              port: rpc
          {{- end }}
          {{- /* Default to tcpSocket (works with TLS); users may override per-service via server.<svc>.readinessProbe. */ -}}
          {{- $resolvedProbe := default $.Values.server.readinessProbe $serviceValues.readinessProbe }}
          {{- if $resolvedProbe }}
          readinessProbe:
          {{- toYaml $resolvedProbe | nindent 12 }}
          {{- else if ne $service "worker" }}
          readinessProbe:
            tcpSocket:
              port: rpc
          {{- end }}
          volumeMounts:
            - name: config
              mountPath: /etc/temporal/config/config_template.yaml
              subPath: config_template.yaml
            - name: dynamic-config
              mountPath: /etc/temporal/dynamic_config
            {{- if $.Values.shims.dockerize }}
            - name: shims
              mountPath: /usr/local/bin/dockerize
              subPath: dockerize
            {{- end }}
            {{- if $.Values.server.additionalVolumeMounts }}
            {{- toYaml $.Values.server.additionalVolumeMounts | nindent 12}}
            {{- end }}
            {{- if or $.Values.server.tls.internode.enabled $.Values.server.tls.frontend.enabled }}
            {{- include "temporal.server.tls.volumeMounts" $ | nindent 12 }}
            {{- end }}
          resources:
            {{- toYaml (default $.Values.server.resources $serviceValues.resources) | nindent 12 }}
          {{- with $serviceValues.containerSecurityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      {{- with $.Values.imagePullSecrets }}
      imagePullSecrets:
      {{- toYaml . | nindent 8 }}
      {{- end }}
      volumes:
        {{- if $.Values.shims.dockerize }}
        - name: shims
          configMap:
            name: "{{ include "temporal.fullname" $ }}-shims"
            defaultMode: 0555
        {{- end }}
        - name: config
          configMap:
            name: "{{ include "temporal.fullname" $ }}-config"
        - name: dynamic-config
          configMap:
            name: "{{ include "temporal.fullname" $ }}-dynamic-config"
            items:
            - key: dynamic_config.yaml
              path: dynamic_config.yaml
        {{- if $.Values.server.additionalVolumes }}
        {{- toYaml $.Values.server.additionalVolumes | nindent 8}}
        {{- end }}
        {{- if or $.Values.server.tls.internode.enabled $.Values.server.tls.frontend.enabled }}
        {{- include "temporal.server.tls.volumes" $ | nindent 8 }}
        {{- end }}
      {{- with (default $.Values.server.nodeSelector $serviceValues.nodeSelector) }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    {{- with (default $.Values.server.affinity $serviceValues.affinity) }}
      affinity:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with (default $.Values.server.tolerations $serviceValues.tolerations) }}
      tolerations:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with $serviceValues.topologySpreadConstraints }}
      topologySpreadConstraints:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with (default $.Values.server.schedulerName $serviceValues.schedulerName) }}
      schedulerName: {{ . }}
    {{- end }}
    {{- with (default $.Values.server.runtimeClassName $serviceValues.runtimeClassName) }}
      runtimeClassName: {{ . }}
    {{- end }}
    {{- with (default $.Values.server.priorityClassName $serviceValues.priorityClassName) }}
      priorityClassName: {{ . }}
    {{- end }}
      terminationGracePeriodSeconds: {{ default $.Values.server.terminationGracePeriodSeconds $serviceValues.terminationGracePeriodSeconds }}
---
{{- end }}
{{- end }}
{{- end }}
